window.QUIZ_BANK['playwright'] = (window.QUIZ_BANK['playwright']||[]).concat([
{id:4701,topic:'playwright',difficulty:'beginner',question:'Which GitHub Actions official action is commonly used to install Playwright browsers and OS dependencies in CI?',options:['actions/setup-playwright','microsoft/playwright-github-action','playwright-community/setup','npx playwright install --with-deps (run via standard run step)'],answer:3,explanation:'Playwright is typically installed in GitHub Actions workflows by executing `npx playwright install --with-deps` inside a standard `run` step after `npm ci`. This ensures both browser binaries and their system-level operating system dependencies are installed properly for reliable headless execution.'},
{id:4702,topic:'playwright',difficulty:'intermediate',question:'What is the purpose of passing `--reporter=github` when running Playwright tests in GitHub Actions?',options:['It automatically creates pull requests for failing tests','It produces GitHub Actions workflow annotations directly on changed files in PRs','It syncs test results to GitHub Issues','It requires GitHub personal access token authentication for tests'],answer:1,explanation:'The `github` reporter formats test failures as GitHub Actions workflow annotations. These annotations appear inline within the pull request files tab and in the workflow summary, highlighting exact lines where assertion failures occurred alongside detailed stack traces.'},
{id:4703,topic:'playwright',difficulty:'intermediate',question:'In a GitHub Actions workflow YAML file, which configuration ensures that HTML report artifacts are uploaded even if tests fail?',options:['if: always()','if: failure()','continue-on-error: true','upload-always: true'],answer:0,explanation:'Using `if: always()` on the artifact upload step ensures that the test report is preserved regardless of whether the test execution step passed, failed, or was cancelled, enabling developers to inspect traces, screenshots, and error logs post-run.'},
{id:4704,topic:'playwright',difficulty:'beginner',question:'What is the official Microsoft Docker container repository for Playwright?',options:['docker.io/playwright/node','mcr.microsoft.com/playwright','registry.hub.docker.com/microsoft/playwright-runner','ghcr.io/playwright/browsers'],answer:1,explanation:'Microsoft publishes official Playwright Docker images to the Microsoft Container Registry (MCR) under `mcr.microsoft.com/playwright:<version>`. These images come pre-configured with browser binaries, fonts, media codecs, and all required Linux system dependencies for immediate execution.'},
{id:4705,topic:'playwright',difficulty:'intermediate',question:'Why is an Xvfb (X Virtual Framebuffer) server generally unnecessary when running Playwright inside official Docker images?',options:['Docker containers cannot run GUI applications','Playwright launches headless Chromium, Firefox, and WebKit natively without requiring an X11 server','Playwright includes an internal Wayland compositor','Official images replace all browsers with text-only emulators'],answer:1,explanation:'Playwright communicates directly with browser automation protocols in headless mode across Chromium, Firefox, and WebKit. Because modern headless browsers render offscreen buffers natively, no virtual X11 display server like Xvfb is required for running automated end-to-end suites.'},
{id:4706,topic:'playwright',difficulty:'advanced',question:'When running Playwright in a custom Linux Docker container, which CLI flag installs all required host OS libraries for the browsers?',options:['npx playwright install-sys','npx playwright install --with-deps','npx playwright doctor --fix','npx playwright setup-linux-packages'],answer:1,explanation:'Running `npx playwright install --with-deps` detects the Linux distribution package manager (such as apt-get) and installs all necessary system libraries required for browser processes to execute smoothly without missing shared object errors in custom container environments.'},
{id:4707,topic:'playwright',difficulty:'intermediate',question:'What does the CLI argument `--shard=2/4` instruct the Playwright test runner to do?',options:['Run only the second test file 4 times in parallel','Divide all test files into 4 equal shards and execute shard number 2','Split tests across 2 CPU cores and 4 threads','Run tests in 2 browser contexts with 4 retry attempts'],answer:1,explanation:'Playwright native test sharding splits the test suite across multiple CI jobs. The syntax `--shard=2/4` means the test runner calculates 4 roughly equal partitions of the test files and executes the 2nd shard on the current machine in parallel.'},
{id:4708,topic:'playwright',difficulty:'advanced',question:'When using Playwright test sharding across GitHub Actions matrix jobs, how are the separate shard reports merged into a single comprehensive HTML report?',options:['Using `npx playwright merge-reports --reporter html ./blob-reports`','Using `cat report-* > full-report.html`','Using `npx playwright show-report --aggregate`','Playwright automatically uploads and merges reports across cloud instances'],answer:0,explanation:'When running sharded tests, configuring `reporter: [["blob"]]` produces individual blob report archives per shard. In a follow-up CI step, `npx playwright merge-reports --reporter html ./blob-reports` combines all blob files into a single unified HTML report with full metadata.'},
{id:4709,topic:'playwright',difficulty:'beginner',question:'Which command opens the Playwright HTML report in a local web browser after test execution?',options:['npx playwright view-report','npx playwright open-report','npx playwright show-report','npx playwright report --serve'],answer:2,explanation:'Executing `npx playwright show-report` starts a local HTTP server and automatically opens the default web browser to display the generated interactive HTML report containing test steps, traces, screenshots, and videos for debugging test executions.'},
{id:4710,topic:'playwright',difficulty:'intermediate',question:'How can you attach custom data, such as an API response payload or screenshot, to the current test in Playwright for display in the HTML report?',options:['page.attachData("key", data)','testInfo.attach("name", { body: data, contentType: "application/json" })','test.reportAttachment("name", data)','console.reportAttachment(data)'],answer:1,explanation:'The `testInfo.attach(name, { body, contentType, path })` API attaches arbitrary files, text strings, binary buffers, or logs to the current test execution metadata, rendering them directly in the final HTML report and trace viewer interface.'},
{id:4711,topic:'playwright',difficulty:'intermediate',question:'Which third-party reporter package is standard for integrating Playwright with the Allure reporting framework?',options:['playwright-allure','allure-playwright','jest-allure-playwright','allure-reporter-playwright'],answer:1,explanation:'The `allure-playwright` package is the official integration adapter. It captures test suites, steps, metadata, attachments, and severity levels, writing output files formatted specifically for the Allure report generator engine and web dashboard.'},
{id:4712,topic:'playwright',difficulty:'advanced',question:'How do you configure `allure-playwright` in your `playwright.config.ts` configuration file?',options:['reporter: [["allure-playwright", { outputFolder: "allure-results" }]]','plugins: ["allure-playwright"]','reporters: { allure: true }','testRunner: { allure: { enabled: true } }'],answer:0,explanation:'In `playwright.config.ts`, reporters are defined inside the `reporter` array. You specify `["allure-playwright", { outputFolder: "allure-results" }]` to configure the reporter and set the target output directory for test artifact files during automated execution.'},
{id:4713,topic:'playwright',difficulty:'intermediate',question:'What is Playwright Component Testing (`@playwright/experimental-ct-react`, Vue, Svelte)?',options:['A tool to test backend microservices without UI','A specialized runner that mounts and tests frontend framework UI components in real browser environments','A headless unit test runner using JSDOM','An automated visual regression plugin for Figma designs'],answer:1,explanation:'Playwright Component Testing compiles and mounts isolated UI components (React, Vue, Svelte, Solid) inside real browser engines (Chromium, Firefox, WebKit), allowing full user interaction and visual assertion without running the whole backend app.'},
{id:4714,topic:'playwright',difficulty:'intermediate',question:'In a Playwright React Component Test, which function mounts the component to the DOM for testing?',options:['render(<MyComponent />)','page.mount(<MyComponent />)','mount(<MyComponent />) provided by test fixture','DOM.create(<MyComponent />)'],answer:2,explanation:'Playwright Component Testing provides an augmented `test` fixture that supplies a `mount` function. Calling `const component = await mount(<MyComponent />);` mounts the JSX component into the real browser and returns a Locator for assertion.'},
{id:4715,topic:'playwright',difficulty:'advanced',question:'How can you intercept and inspect outgoing and incoming WebSocket messages in Playwright?',options:['page.on("websocket", ws => { ws.on("framesent", f => ...); ws.on("framereceived", f => ...); })','page.interceptWebSocket((ws) => ws.listen())','page.network.on("websocket", ws => ws.read())','page.route("ws://*", route => route.inspect())'],answer:0,explanation:'Playwright emits a `"websocket"` event on the Page object when a WebSocket connection opens. You attach listeners to `ws.on("framesent", ...)` and `ws.on("framereceived", ...)` to monitor payloads sent and received across the socket connection in real time.'},
{id:4716,topic:'playwright',difficulty:'intermediate',question:'Which browser engine supports generating PDF documents via `page.pdf()` in Playwright?',options:['Firefox only','WebKit only','Chromium in headless mode','All browsers in both headed and headless modes'],answer:2,explanation:'`page.pdf()` relies on the Chromium DevTools Protocol printing feature and is exclusively supported in headless Chromium. Calling `page.pdf()` in Firefox or WebKit throws an unsupported operation error, making Chromium the dedicated PDF generator engine.'},
{id:4717,topic:'playwright',difficulty:'intermediate',question:'Which code snippet correctly exports a web page as an A4 formatted PDF file in Playwright?',options:['await page.exportPDF({ size: "A4", destination: "page.pdf" });','await page.pdf({ path: "page.pdf", format: "A4" });','await page.printToPDF({ file: "page.pdf", paper: "A4" });','await page.saveAsPDF("page.pdf", { pageSize: "A4" });'],answer:1,explanation:'The `page.pdf({ path: "page.pdf", format: "A4" })` method configures paper dimensions to standard A4 format and writes the resulting PDF document to the specified filesystem path asynchronously with full CSS page layout rendering.'},
{id:4718,topic:'playwright',difficulty:'intermediate',question:'How can you extract browser performance timing metrics (e.g., DNS, TCP, DOM content loaded) using Playwright?',options:['await page.evaluate(() => JSON.stringify(window.performance.timing))','page.metrics.getPerformanceMetrics()','page.getTimingEvents()','expect(page).toHaveLoadMetrics()'],answer:0,explanation:'Executing `page.evaluate(() => JSON.stringify(window.performance.timing))` or querying `performance.getEntriesByType("navigation")` evaluates standard browser Performance Navigation Timing APIs directly inside the web page context to retrieve accurate milestone timestamps for custom performance benchmarks and tracking.'},
{id:4719,topic:'playwright',difficulty:'advanced',question:'How do you connect Playwright to a cloud grid provider like BrowserStack or Selenium Grid using CDP?',options:['chromium.connectOverCDP(endpointURL, { headers: { ... } })','playwright.launchGrid({ gridUrl: endpointURL })','browser.remoteConnect(endpointURL)','page.connectRemote(endpointURL)'],answer:0,explanation:'`chromium.connectOverCDP(endpointURL)` connects Playwright directly to an existing browser instance exposed over Chrome DevTools Protocol, which cloud testing services like BrowserStack utilize for remote browser execution across diverse operating systems and physical devices seamlessly.'},
{id:4720,topic:'playwright',difficulty:'beginner',question:'What is a primary architectural difference between Playwright and Cypress regarding multi-tab support?',options:['Cypress supports unlimited tabs; Playwright only supports single tabs','Playwright natively supports multiple tabs, popups, and browser contexts simultaneously; Cypress is restricted to a single active tab','Playwright cannot switch tabs without restarting browser instances','Cypress and Playwright have identical multi-tab handling mechanisms'],answer:1,explanation:'Playwright was architected from the ground up to support multiple browser contexts, tabs, and windows in parallel. Cypress executes inside the browser iframe, traditionally limiting tests to a single primary top-level window.'},
{id:4721,topic:'playwright',difficulty:'intermediate',question:'What is a key difference between Playwright and Puppeteer regarding browser engine support?',options:['Puppeteer supports WebKit and Firefox natively; Playwright only supports Chromium','Playwright supports Chromium, Firefox, and WebKit; Puppeteer historically focused primarily on Chromium and Chrome DevTools Protocol','Playwright cannot run on headless Linux servers','Puppeteer has a built-in cross-browser test runner, while Playwright does not'],answer:1,explanation:'While Puppeteer originated as a Google project focused primarily on Chromium CDP automation, Playwright was designed to automate Chromium, Firefox (Gecko), and WebKit across all desktop operating systems with a uniform API.'},
{id:4722,topic:'playwright',difficulty:'beginner',question:'What is the Page Object Model (POM) in test automation with Playwright?',options:['A design pattern where web pages are represented by classes encapsulating DOM locators and interaction methods','A native Playwright compiler for React components','A database modeling tool built into Playwright test runner','An automated CSS generator for web applications'],answer:0,explanation:'The Page Object Model (POM) is an object-oriented design pattern where application pages or UI sections are abstracted into reusable classes containing element locators and high-level interaction methods, improving test maintainability.'},
{id:4723,topic:'playwright',difficulty:'intermediate',question:'In a Playwright Page Object class, how should element locators typically be defined?',options:['As raw XPath strings evaluated inside each test with document.evaluate','As readonly Locator properties initialized in the constructor using page.getByRole or page.locator','As static CSS selectors declared on the global window object','As hardcoded timeout promises created before navigation'],answer:1,explanation:'In idiomatic TypeScript/JavaScript Playwright POMs, locators are defined as `readonly` class properties initialized in the constructor (e.g. `this.submitBtn = page.getByRole("button", { name: "Submit" })`), providing auto-waiting upon action invocation whenever methods execute.'},
{id:4724,topic:'playwright',difficulty:'intermediate',question:'How do custom test fixtures simplify Page Object Model usage in Playwright test files?',options:['They remove the need to import page objects and instantiate them with `new` in every test by injecting them as fixtures','They convert TypeScript classes into JSON schemas','They force all tests to run sequentially in a single worker process','They automatically generate assertions without writing expect statements'],answer:0,explanation:'Extending `test.extend<{ myPage: MyPage }>` allows you to define fixtures that automatically instantiate page objects, navigate or log in, and pass ready-to-use page object instances directly into test function parameters.'},
{id:4725,topic:'playwright',difficulty:'advanced',question:'How can you create a reusable component fixture for a Navigation Bar in Playwright using `test.extend`?',options:['test.extend({ navBar: async ({ page }, use) => { await use(new NavBarComponent(page)); } })','test.fixture("navBar", () => new NavBarComponent())','test.use({ navBar: page.locator("nav") })','page.registerComponent("navBar", NavBarComponent)'],answer:0,explanation:'Using `baseTest.extend<{ navBar: NavBarComponent }>({ navBar: async ({ page }, use) => { await use(new NavBarComponent(page)); } })` declares a test-scoped fixture that instantiates the component and provides it to any test requesting `navBar`.'},
{id:4726,topic:'playwright',difficulty:'advanced',question:'What is worker scope in Playwright fixtures, and when should it be used for test data setup?',options:['It runs before every single test to clear browser cookies','It executes once per worker process, ideal for expensive operations like database seeding or spinning up container services','It restricts test execution to a single CPU thread','It prevents network mocking across all worker threads'],answer:1,explanation:'Worker-scoped fixtures execute once per worker process lifecycle rather than once per test. They are optimal for expensive initialization tasks, such as seeding test databases, starting mock backend servers, or generating common auth tokens.'},
{id:4727,topic:'playwright',difficulty:'intermediate',question:'In a fast API+UI hybrid test, how should a test log in before performing UI actions?',options:['Fill username and password fields on the login page in every test case','Send a POST request to the login endpoint via APIRequestContext, extract cookies/tokens, and inject them into the BrowserContext','Manually click through OAuth login flows with 5-second delays','Store credentials in local storage using plain text files on disk'],answer:1,explanation:'The API+UI hybrid approach uses `request.post("/api/login")` to obtain session cookies or tokens programmatically, injecting them into the `BrowserContext` via `context.addCookies()` or `context.storageState()`, bypassing slow UI login forms to accelerate test suites.'},
{id:4728,topic:'playwright',difficulty:'intermediate',question:'When migrating from Selenium WebDriver to Playwright, what is the equivalent of `driver.findElement(By.id("username")).sendKeys("admin")`?',options:['await page.type("#username", "admin")','await page.locator("#username").fill("admin")','await page.keyboard.press("#username", "admin")','await page.setElementValue("#username", "admin")'],answer:1,explanation:'In Playwright, `locator.fill("admin")` is the modern equivalent. It waits for the element to be visible, clears existing text, and fills the new value, triggering appropriate input and change events reliably.'},
{id:4729,topic:'playwright',difficulty:'intermediate',question:'What is the Playwright equivalent of Selenium\'s `WebDriverWait(driver, 10).until(EC.visibilityOfElementLocated(...))`?',options:['await page.waitForManualVisibility(selector, 10000)','await expect(locator).toBeVisible()','await page.sleep(10000)','driver.wait(locator)'],answer:1,explanation:'Playwright locators and web-first assertions like `await expect(locator).toBeVisible()` have built-in auto-waiting and retry mechanisms, eliminating the need for explicit boilerplate wait conditions required in Selenium testing architectures and reducing test flakiness significantly.'},
{id:4730,topic:'playwright',difficulty:'beginner',question:'Which locator strategy is prioritized as best practice in Playwright documentation for element selection?',options:['XPath locators (`page.locator("//div/button[2]")`)','User-facing locators (`page.getByRole`, `page.getByText`, `page.getByLabel`)','CSS ID selectors (`page.locator("#btn-34a")`)','Tag name queries (`page.locator("button")`)'],answer:1,explanation:'Playwright recommends user-facing locators (e.g., `getByRole`, `getByText`, `getByLabel`, `getByPlaceholder`) because they mirror how users and assistive technologies interact with the page, making tests resilient to internal DOM refactoring and CSS updates.'},
{id:4731,topic:'playwright',difficulty:'beginner',question:'Why is `page.waitForTimeout(5000)` considered a major anti-pattern in Playwright test suites?',options:['It causes the browser engine to crash on CI runners','It introduces arbitrary test flakiness, slows down suite execution, and ignores Playwright\'s built-in auto-waiting mechanism','It is deprecated and throws runtime exceptions in TypeScript','It only pauses the test runner on macOS operating systems'],answer:1,explanation:'Hardcoded sleep timeouts (`page.waitForTimeout`) waste CI time if the condition completes earlier and fail intermittently if network or rendering latency exceeds the fixed duration. Web-first assertions and auto-waiting should always be preferred.'},
{id:4732,topic:'playwright',difficulty:'intermediate',question:'Why is relying heavily on complex, deep CSS selectors (e.g., `div > div.col-md-4 > span:nth-child(2)`) discouraged in Playwright tests?',options:['Playwright cannot parse CSS child combinators','They are brittle and break when HTML layout or styling changes, even if application behavior remains unchanged','CSS selectors disable Playwright auto-waiting functionality','They require extra NPM compilation dependencies'],answer:1,explanation:'Deep structural CSS selectors tie tests to brittle DOM hierarchy details. Any styling update or refactor breaks the selector. Using semantic locators like `getByRole("button", { name: "Submit" })` isolates tests from structural changes.'},
{id:4733,topic:'playwright',difficulty:'intermediate',question:'How can you mock an API endpoint `/api/users` to return a mock JSON list with a 200 OK status using `page.route`?',options:['await page.route("**/api/users", route => route.fulfill({ status: 200, json: [{ id: 1, name: "Alice" }] }));','await page.mockResponse("/api/users", [{ id: 1, name: "Alice" }]);','await page.intercept("/api/users", { body: [{ id: 1, name: "Alice" }] });','await page.on("request", r => r.respond({ status: 200 }));'],answer:0,explanation:'`page.route(urlPattern, handler)` intercepts matching network requests. Inside the handler, calling `route.fulfill({ status: 200, json: [...] })` provides the mocked response directly to the browser without hitting the actual server backend or external service.'},
{id:4734,topic:'playwright',difficulty:'intermediate',question:'Which Playwright assertion is used for visual regression screenshot testing on a page or locator?',options:['await expect(page).toMatchVisualDesign()','await expect(page).toHaveScreenshot()','await expect(page).toEqualImage("baseline.png")','expect(page.screenshot()).toBeValid()'],answer:1,explanation:'`await expect(page).toHaveScreenshot()` captures a screenshot of the page and compares it pixel-by-pixel against a baseline golden snapshot stored on disk. It can also be called on specific locators: `await expect(locator).toHaveScreenshot()`.'},
{id:4735,topic:'playwright',difficulty:'advanced',question:'In `expect(page).toHaveScreenshot({ maxDiffPixels: 100, threshold: 0.2 })`, what does the `threshold` option represent?',options:['The maximum number of seconds to wait for screenshot rendering','The acceptable perceived color difference between two corresponding pixels in YIQ color space (0 to 1)','The percentage of the total image that is allowed to change','The opacity level of the diff overlay mask image'],answer:1,explanation:'The `threshold` option ranges from 0 to 1 and configures the acceptable color difference per pixel based on the YIQ color space algorithm. Lower values enforce stricter pixel color matching.'},
{id:4736,topic:'playwright',difficulty:'intermediate',question:'Which CLI flag command updates all baseline visual snapshot images when intentional UI changes are made?',options:['npx playwright test --update-snapshots','npx playwright test --overwrite-images','npx playwright refresh-baseline','npx playwright snapshot --save'],answer:0,explanation:'Running `npx playwright test --update-snapshots` (or `-u`) instructs the test runner to re-capture all screenshot and snapshot assertions and overwrite the stored baseline golden files on disk with the newly rendered results.'},
{id:4737,topic:'playwright',difficulty:'beginner',question:'What is Playwright\'s default storage isolation model between separate test files and test cases?',options:['All tests share a single global browser instance and cookies across the entire test run','Every single test executes in an isolated, brand-new BrowserContext with fresh cookies and local storage','Storage is preserved automatically between tests unless manually deleted with page.clearData()','Tests share storage within the same describe block only'],answer:1,explanation:'Playwright guarantees test isolation by default. Every test gets a fresh `BrowserContext` and `Page` fixture with empty cookies, localStorage, and cache, preventing test contamination without expensive browser restarts across the entire suite.'},
{id:4738,topic:'playwright',difficulty:'intermediate',question:'How do you configure HTTP Basic Authentication credentials for all requests in a Playwright test file or context?',options:['await page.authenticate({ username: "user", password: "pwd" });','browser.newContext({ httpCredentials: { username: "user", password: "pwd" } })','page.setHttpHeader("Authorization", "Basic ...")','context.setCredentials("user", "pwd")'],answer:1,explanation:'Passing `httpCredentials: { username: "user", password: "pwd" }` to `browser.newContext()` or `test.use({ httpCredentials: { ... } })` automatically responds to HTTP 401 Basic or Digest authentication challenges across that context.'},
{id:4739,topic:'playwright',difficulty:'advanced',question:'How can a single Playwright test simulate real-time chat interactions between two distinct users concurrently?',options:['By launching two separate browser processes with exec()','By creating two isolated BrowserContext instances within the same test, each with its own Page','By opening two tabs in the same default BrowserContext','Playwright does not support multiple users in a single test'],answer:1,explanation:'A test can call `const userContext1 = await browser.newContext(); const userContext2 = await browser.newContext();` to simulate multiple independent users with distinct sessions, cookies, and permissions interacting simultaneously in real time.'},
{id:4740,topic:'playwright',difficulty:'advanced',question:'How do you load a Chrome browser extension for testing in Playwright with Chromium?',options:['chromium.launchPersistentContext(userDataDir, { args: ["--disable-extensions-except=/path/to/ext", "--load-extension=/path/to/ext"] })','page.installExtension("/path/to/ext")','chromium.launch({ extensions: ["/path/to/ext"] })','browser.loadPlugin("/path/to/ext")'],answer:0,explanation:'Extensions in Chromium require a persistent context and specific Chromium CLI arguments. You launch with `chromium.launchPersistentContext(dir, { args: ["--disable-extensions-except=...", "--load-extension=..."], headless: false })` to load unpacked extension manifests properly during tests.'},
{id:4741,topic:'playwright',difficulty:'intermediate',question:'Where do you define multi-browser test matrices (Chromium, Firefox, WebKit, Mobile Safari) in a Playwright project?',options:['Inside the `projects` array in `playwright.config.ts`','In individual `.env` environment files per browser','In `package.json` under the `"browsers"` key','Inside a `.playwrightrc` XML file'],answer:0,explanation:'The `projects` array inside `playwright.config.ts` specifies test targets, defining distinct browser names, device descriptors (`devices["iPhone 14"]`), viewport sizes, and contextual settings to run in parallel matrix execution across workers with isolated configurations.'},
{id:4742,topic:'playwright',difficulty:'intermediate',question:'What does `test.describe.serial()` configure for tests within that describe block?',options:['It runs the tests in parallel on separate worker threads','It runs the tests sequentially in the same worker process; if one test fails, all subsequent tests in the block are skipped','It runs tests in alphabetical order without timeouts','It repeats tests 3 times sequentially to verify stability'],answer:1,explanation:'`test.describe.serial()` ensures that tests in the block execute strictly sequentially in a single worker. If any test in the serial block fails, execution immediately halts, skipping the remaining dependent tests in that group.'},
{id:4743,topic:'playwright',difficulty:'intermediate',question:'How does Playwright integrate with AI visual testing platforms such as Applitools Eyes or Percy?',options:['By using third-party SDK packages (`@applitools/eyes-playwright`, `@percy/playwright`) that take DOM snapshots and upload them to AI visual grids','By embedding custom Python neural networks into page.evaluate','By replacing Playwright test runner with Selenium grid drivers','AI testing is natively built into Playwright core without third-party libraries'],answer:0,explanation:'Platforms like Applitools and Percy provide official Playwright SDK wrappers (e.g., `@applitools/eyes-playwright`, `@percy/playwright`) that capture DOM snapshots or visual renders and send them to cloud AI engines for automated visual regression analysis.'},
{id:4744,topic:'playwright',difficulty:'intermediate',question:'What is the purpose of `playwright.config.ts` option `webServer`?',options:['To host the test results HTML dashboard on AWS S3','To automatically launch a local development/backend server before starting tests and shut it down upon completion','To serve static mocked JSON files over WebSockets','To open a proxy server for cross-origin CORS requests'],answer:1,explanation:'The `webServer` property in `playwright.config.ts` specifies a command (e.g. `npm run start`) and URL to automatically start the local application under test before tests run and wait until the URL is ready before executing tests.'},
{id:4745,topic:'playwright',difficulty:'advanced',question:'In `playwright.config.ts`, what does setting `reuseExistingServer: !process.env.CI` inside `webServer` accomplish?',options:['It prevents the web server from ever restarting in CI environments','It reuses an already running local development server on developer machines, while forcing a fresh server start in CI pipelines','It clones the server across multiple worker processes','It caches API responses across separate test runs'],answer:1,explanation:'Setting `reuseExistingServer: !process.env.CI` tells Playwright to reuse an existing local development server if already running locally on localhost, saving startup time during development while ensuring clean fresh server instances in CI.'},
{id:4746,topic:'playwright',difficulty:'intermediate',question:'How do you execute only tests that have a specific tag, such as `@smoke`, in Playwright CLI?',options:['npx playwright test --grep "@smoke"','npx playwright test --filter "smoke"','npx playwright test --tag smoke','npx playwright test --only-tags "@smoke"'],answer:0,explanation:'The `--grep` CLI argument filters tests by matching title strings or regex patterns. Passing `npx playwright test --grep "@smoke"` matches any test or describe block whose title contains `@smoke` during test discovery.'},
{id:4747,topic:'playwright',difficulty:'intermediate',question:'How can you inverse-filter tests to skip all tests tagged with `@slow` using the CLI?',options:['npx playwright test --grep-invert "@slow"','npx playwright test --skip "@slow"','npx playwright test --exclude "@slow"','npx playwright test --no-tag "@slow"'],answer:0,explanation:'The `--grep-invert` option filters out any tests matching the specified regular expression or tag string, allowing you to run the remaining fast tests while skipping long-running suites during rapid local feedback loops.'},
{id:4748,topic:'playwright',difficulty:'intermediate',question:'What is the difference between `page.screenshot()` and `locator.screenshot()` in Playwright?',options:['`page.screenshot()` captures the entire viewport or full page, while `locator.screenshot()` captures only the bounding box of the specified element','`locator.screenshot()` only works on SVG elements','`page.screenshot()` requires headless mode; `locator.screenshot()` requires headed mode','There is no difference; they are exact aliases'],answer:0,explanation:'`page.screenshot()` captures the visible viewport (or entire scrollable document with `{ fullPage: true }`), whereas `locator.screenshot()` isolates and captures the specific matched element and its contents only without background clutter.'},
{id:4749,topic:'playwright',difficulty:'advanced',question:'How can you mask dynamic elements (e.g., timestamps or user avatars) when taking a visual screenshot assertion in Playwright?',options:['await expect(page).toHaveScreenshot({ mask: [page.locator(".timestamp"), page.locator(".avatar")] })','await page.hideElements([".timestamp", ".avatar"])','await expect(page).toHaveScreenshot({ ignoreSelectors: [".timestamp"] })','page.setMaskingRule(".timestamp", true)'],answer:0,explanation:'The `mask` option accepts an array of Locators. Playwright overlays pink bounding boxes on top of those elements before capturing the screenshot, excluding dynamic or volatile content from visual diff comparisons.'},
{id:4750,topic:'playwright',difficulty:'intermediate',question:'What does `route.abort()` do when intercepting network traffic in Playwright?',options:['It cancels the test immediately with an error','It terminates the browser process','It aborts the network request, causing it to fail as if blocked by network failure or adblockers','It restarts the HTTP connection'],answer:2,explanation:'`route.abort()` simulates a network failure (such as `failed`, `connectionreset`, or `blockedbyclient`) for matching requests, which is essential for testing application offline states, error boundaries, and failed API resilience under adverse conditions.'},
{id:4751,topic:'playwright',difficulty:'advanced',question:'How can you simulate a slow network connection (network throttling) for a specific browser session in Chromium using Playwright?',options:['const cdp = await context.newCDPSession(page); await cdp.send("Network.emulateNetworkConditions", { offline: false, latency: 100, downloadThroughput: 50000, uploadThroughput: 50000 });','page.setNetworkSpeed("slow3G")','context.throttleNetwork({ delay: 500 })','page.route("**", route => route.delay(500))'],answer:0,explanation:'By creating a Chrome DevTools Protocol session via `context.newCDPSession(page)`, tests can send raw CDP commands such as `Network.emulateNetworkConditions` to accurately throttle throughput and inject network latency into the browser session.'},
{id:4752,topic:'playwright',difficulty:'intermediate',question:'What is the recommended approach for handling authentication state reuse across multiple test files in Playwright?',options:['Log in via UI in a `beforeEach` hook in every single test file','Use a global setup project to log in once, save storage state to a JSON file via `page.context().storageState({ path })`, and configure projects to use that file','Hardcode auth session cookies directly into git repository source files','Disable authentication on the backend server for all test environments'],answer:1,explanation:'Playwright\'s authentication reuse pattern involves a `global-setup` script or setup project that logs in once, exports the authenticated state via `storageState()`, and specifies `storageState: "auth.json"` in project configuration for subsequent test workers.'},
{id:4753,topic:'playwright',difficulty:'intermediate',question:'In `playwright.config.ts`, what does the `retries` setting configure?',options:['The number of times an individual locator action retries before timing out','The number of times a failing test is automatically re-executed in CI or local environments','The number of network retry attempts for failed HTTP 500 requests','The number of worker threads to spawn'],answer:1,explanation:'The `retries` configuration determines how many times a test will be automatically re-executed if it fails. It is common to set `retries: process.env.CI ? 2 : 0` to mitigate transient flakiness in CI pipelines.'},
{id:4754,topic:'playwright',difficulty:'beginner',question:'Which CLI command runs only a single specific test file in Playwright?',options:['npx playwright test tests/login.spec.ts','npx playwright run tests/login.spec.ts','npx playwright execute --file tests/login.spec.ts','npx playwright test --spec=tests/login.spec.ts'],answer:0,explanation:'Passing the relative file path directly as an argument to `npx playwright test tests/login.spec.ts` instructs the test runner to execute only tests defined within that designated test file, avoiding unnecessary execution of other suites.'},
{id:4755,topic:'playwright',difficulty:'intermediate',question:'What does `test.describe.parallel()` specify (deprecated in favor of default parallelism / `test.describe.configure`)?',options:['It enforces sequential execution of all tests in the file','It explicitly configures all tests within the describe block to run in parallel across available worker processes','It runs tests simultaneously in one single thread without isolation','It duplicates every test across 5 browsers'],answer:1,explanation:'`test.describe.parallel()` configured tests within that group to run concurrently across worker threads. In modern Playwright, tests run in parallel by default, or you can configure `test.describe.configure({ mode: "parallel" })` explicitly per suite.'},
{id:4756,topic:'playwright',difficulty:'intermediate',question:'How can you configure a test file to run in serial mode using `test.describe.configure`?',options:['test.describe.configure({ mode: "serial" });','test.setMode("serial");','test.config({ serial: true });','test.use({ executionMode: "serial" });'],answer:0,explanation:'`test.describe.configure({ mode: "serial" })` sets the execution mode of the current file or describe block to serial, ensuring tests run in order and abort subsequent tests upon any failure encountered during the sequence.'},
{id:4757,topic:'playwright',difficulty:'advanced',question:'In Playwright fixtures, what is the role of the `use` function passed to fixture definitions?',options:['It imports external npm modules into the fixture','It provides the initialized fixture value to the test and suspends execution until the test teardown completes','It asserts that the fixture is non-null','It logs fixture execution metrics to console'],answer:1,explanation:'In Playwright fixtures, `await use(fixtureValue)` yields the created resource to the test body. Code before `use` runs as setup, and code after `use` executes as teardown after the test finishes, providing clean lifecycle management.'},
{id:4758,topic:'playwright',difficulty:'advanced',question:'How can you create an automatic (auto: true) fixture in Playwright that runs for every test without being explicitly requested?',options:['test.extend({ autoLogger: [async ({ page }, use) => { console.log(page.url()); await use(); }, { auto: true }] })','test.autoFixture("logger", async () => { ... })','test.use({ auto: true })','page.addAutoHook(async () => { ... })'],answer:0,explanation:'By passing tuple configuration `[async ({ ... }, use) => { ... }, { auto: true }]` when defining a fixture via `test.extend()`, the fixture executes automatically for every test in scope without needing to be listed in test arguments.'},
{id:4759,topic:'playwright',difficulty:'intermediate',question:'How do you download a file and verify its suggested filename in Playwright?',options:['const downloadPromise = page.waitForEvent("download"); await page.getByText("Download").click(); const download = await downloadPromise; expect(download.suggestedFilename()).toBe("report.pdf");','const file = await page.clickAndDownload("Download"); expect(file.name).toBe("report.pdf");','const download = page.getDownloadedFile(); expect(download.filename).toBe("report.pdf");','await expect(page).toHaveDownloadedFile("report.pdf");'],answer:0,explanation:'Setting up `const downloadPromise = page.waitForEvent("download")` before triggering the action guarantees the event is captured. You then await the download object and call `download.suggestedFilename()` to verify the file name deterministically.'},
{id:4760,topic:'playwright',difficulty:'intermediate',question:'Where are downloaded files saved by default during Playwright test execution if not saved via `download.saveAs()`?',options:['In the user\'s default OS Downloads folder permanently','In temporary folders that are automatically deleted when the browser context is closed','In the root project directory under `./downloads`','In the browser\'s internal IndexedDB database'],answer:1,explanation:'Playwright streams downloads to isolated temporary folders that are automatically cleaned up when the corresponding `BrowserContext` closes, unless you explicitly persist them to disk using `await download.saveAs(path)` in your test logic.'},
{id:4761,topic:'playwright',difficulty:'beginner',question:'Which Playwright locator method finds an input element based on its associated `<label>` text?',options:['page.getByText()','page.getByLabel()','page.getByInput()','page.getByFormLabel()'],answer:1,explanation:'`page.getByLabel("Username")` locates the input control associated with a `<label>` element matching the text, either via wrapping `<label>` or through matching `for`/`id` attributes, following standard web accessibility guidelines and user expectations.'},
{id:4762,topic:'playwright',difficulty:'beginner',question:'Which Playwright locator method is best suited for locating an input field by its placeholder text attribute?',options:['page.getByPlaceholder("Enter email")','page.getByText("Enter email")','page.getByHint("Enter email")','page.getByRole("textbox", { placeholder: "Enter email" })'],answer:0,explanation:'`page.getByPlaceholder("Enter email")` targets input elements matching their `placeholder` attribute text, providing an intuitive locator for forms without explicit visual label tags while maintaining clean, self-documenting, resilient, and readable test syntax.'},
{id:4763,topic:'playwright',difficulty:'intermediate',question:'What is the advantage of using `page.getByTestId("submit-btn")` in Playwright?',options:['It speeds up browser rendering by 50%','It locates elements by a dedicated testing attribute (`data-testid`), isolating test selectors from CSS and layout refactoring','It bypasses DOM security policies','It allows clicking on disabled buttons without error'],answer:1,explanation:'`getByTestId` queries elements by explicit test IDs (`data-testid` by default). This provides a resilient fallback when semantic accessibility roles or text labels are not feasible or change frequently across UI updates.'},
{id:4764,topic:'playwright',difficulty:'intermediate',question:'How can you customize the default test id attribute name from `data-testid` to `data-cy` or `data-qa` in Playwright?',options:['playwright.selectors.setTestIdAttribute("data-cy") in playwright.config.ts or test files','test.use({ testId: "data-cy" })','page.setTestIdPrefix("data-cy")','It is fixed to data-testid and cannot be changed'],answer:0,explanation:'Calling `selectors.setTestIdAttribute("data-cy")` (or configuring `use: { testIdAttribute: "data-cy" }` in `playwright.config.ts`) reconfigures the attribute that `page.getByTestId()` matches across all tests in the project without requiring any rewriting of existing locator query statements.'},
{id:4765,topic:'playwright',difficulty:'advanced',question:'How can you route and mock an API call while still fetching the real response and modifying a portion of its JSON payload?',options:['await page.route("**/api/user", async route => { const res = await route.fetch(); const json = await res.json(); json.name = "Modified Name"; await route.fulfill({ response: res, json }); });','await page.route("**/api/user", route => route.modify({ name: "Modified Name" }));','await page.overrideResponse("**/api/user", { name: "Modified Name" });','route.continue({ patch: { name: "Modified Name" } })'],answer:0,explanation:'`route.fetch()` performs the real backend network request from Node.js, allowing the test to inspect, modify the JSON response body, and fulfill the intercepted route with the modified data using `route.fulfill({ response: res, json })`.'},
{id:4766,topic:'playwright',difficulty:'intermediate',question:'What does `page.unroute()` do in Playwright?',options:['Disables all browser networking completely','Removes a previously registered route handler matching the specified URL pattern','Clears all browser navigation history','Resets the browser proxy configuration'],answer:1,explanation:'`page.unroute(urlPattern, handler?)` unregisters network interception handlers previously set by `page.route()`, restoring default un-intercepted network request behavior for matching URLs throughout subsequent navigation and fetch actions across the active page context.'},
{id:4767,topic:'playwright',difficulty:'intermediate',question:'What is the purpose of `testInfo.status` and `testInfo.expectedStatus` in Playwright test hooks?',options:['To check whether a test is expected to fail (e.g. marked with test.fail()) and inspect actual execution outcome','To set HTTP status codes on API routes','To restart the operating system when memory is low','To measure network bandwidth'],answer:0,explanation:'`testInfo.status` contains the outcome of the test run (`passed`, `failed`, `timedOut`, `skipped`), while `testInfo.expectedStatus` reflects whether the test was marked with `test.fail()` (`failed` vs `passed`), useful for custom reporting and analytics.'},
{id:4768,topic:'playwright',difficulty:'advanced',question:'How can you configure Playwright to take a full-page screenshot automatically only when a test fails in CI?',options:['In `playwright.config.ts`, set `use: { screenshot: "only-on-failure" }`','Set `page.autoScreenshot("on-failure")` in beforeEach','Pass `--screenshot-failures` to CLI','Add `test.onFailure(() => page.screenshot())` in every test'],answer:0,explanation:'In `playwright.config.ts`, setting `use: { screenshot: "only-on-failure" }` automatically captures and attaches screenshots to the test report whenever a test encounters an assertion error or timeout, saving storage on passing runs.'},
{id:4769,topic:'playwright',difficulty:'intermediate',question:'What does configuring `trace: "retain-on-failure"` in `playwright.config.ts` do?',options:['It records execution traces for every test but discards traces for passing tests, preserving traces only when tests fail','It retains trace files for 30 days on disk','It enables traces only on the second retry attempt','It streams traces live over WebRTC'],answer:0,explanation:'`trace: "retain-on-failure"` records full Playwright trace data (DOM snapshots, network traffic, actions) during test execution, but immediately deletes trace archives if the test passes, keeping artifacts small while debugging failures.'},
{id:4770,topic:'playwright',difficulty:'beginner',question:'Which Playwright tool allows you to visually step through an execution trace, view DOM snapshots, console logs, and network calls post-test?',options:['Playwright Inspector (`npx playwright test --debug`)','Playwright Trace Viewer (`npx playwright show-trace trace.zip`)','Chrome Developer Tools Profiler','Playwright Codegen Studio'],answer:1,explanation:'Playwright Trace Viewer (`npx playwright show-trace <path-to-trace.zip>`) is a GUI tool that enables deep post-mortem analysis of test runs, showing action timelines, before/after DOM snapshots, network requests, and console logs.'},
{id:4771,topic:'playwright',difficulty:'advanced',question:'How do you programmatically start and stop custom trace recording inside a specific test case?',options:['await context.tracing.start({ screenshots: true, snapshots: true }); /* actions */ await context.tracing.stop({ path: "trace.zip" });','await page.startTrace(); /* actions */ await page.saveTrace("trace.zip");','await browser.recordTrace("trace.zip");','page.tracing.enable();'],answer:0,explanation:'`context.tracing.start({ screenshots: true, snapshots: true, sources: true })` starts trace recording on a BrowserContext, and `context.tracing.stop({ path: "trace.zip" })` finalizes and saves the zip archive to disk for subsequent offline debugging.'},
{id:4772,topic:'playwright',difficulty:'intermediate',question:'What does the `workers` option in `playwright.config.ts` control?',options:['The maximum number of concurrent worker processes running tests in parallel','The number of browser windows opened per test','The count of CPU cores assigned to Docker','The number of background Web Workers spawned inside JavaScript'],answer:0,explanation:'The `workers` setting (e.g. `workers: 4` or `workers: "50%"`) controls how many distinct Node.js worker processes are spawned simultaneously to execute test files in parallel across available CPU resources on the host machine.'},
{id:4773,topic:'playwright',difficulty:'intermediate',question:'When running tests with multiple worker processes in Playwright, how is state shared between workers?',options:['Workers share global JavaScript variables in memory','Workers run in completely separate Node.js processes with isolated memory; no runtime state is shared between workers','Workers synchronize memory via Redis by default','Workers share the same browser instance and context'],answer:1,explanation:'Each Playwright worker is an isolated operating system process with its own memory space and browser instances. Runtime variables, mocks, and memory states are not shared between different worker processes.'},
{id:4774,topic:'playwright',difficulty:'advanced',question:'How can you share a unique database ID or auth token generated in a worker across all tests running in that same worker process?',options:['By using a worker-scoped fixture (`scope: "worker"`) created via `test.extend`','By saving the ID in a global Node.js variable in `beforeEach`','By writing the ID to a shared global window property in Chromium','By passing the value in HTTP request headers'],answer:0,explanation:'Worker-scoped fixtures (`scope: "worker"`) are instantiated once per worker process lifecycle. All test cases executing inside that worker receive the same fixture instance, making it ideal for sharing worker-specific setup.'},
{id:4775,topic:'playwright',difficulty:'beginner',question:'What does `expect(locator).toBeDisabled()` verify in Playwright?',options:['The element has CSS opacity set to 0','The element is a disabled form control (e.g. has `disabled` attribute or aria-disabled="true") and cannot be interacted with','The element is hidden from the screen','The element has no click event listeners attached'],answer:1,explanation:'`await expect(locator).toBeDisabled()` checks that the target element is disabled for user interaction (such as a button or input with the `disabled` HTML attribute or appropriate ARIA semantics), retrying until the condition is met.'},
{id:4776,topic:'playwright',difficulty:'intermediate',question:'What does `expect(locator).toBeFocused()` verify in Playwright?',options:['The element is currently visible in the viewport','The element is the current active element (`document.activeElement`) in the page','The element has a hover border effect','The mouse cursor is hovering over the element'],answer:1,explanation:'`await expect(locator).toBeFocused()` verifies that the matched DOM element currently holds input focus (matching `document.activeElement`), auto-retrying until focus is acquired or timeout occurs during asynchronous rendering cycles and dynamic DOM updates.'},
{id:4777,topic:'playwright',difficulty:'intermediate',question:'How does `locator.scrollIntoViewIfNeeded()` work in Playwright?',options:['It forces the page to scroll to the very top before clicking','It scrolls the element into the visible viewport if it is not already visible, prior to performing actions','It zooms the page in to focus on the element','It opens the element in a new modal view'],answer:1,explanation:'`locator.scrollIntoViewIfNeeded()` programmatically scrolls the DOM container or document until the target element is within the visible viewport. Playwright action commands perform this step automatically before clicking or typing to ensure interactive accessibility.'},
{id:4778,topic:'playwright',difficulty:'intermediate',question:'What is the effect of passing `{ timeout: 0 }` to a Playwright action or assertion?',options:['The action will timeout instantly in 0 milliseconds','The action disables the timeout completely and will wait indefinitely until the condition passes or the global test timeout is reached','It sets the timeout to the default 30 seconds','It throws a TypeError'],answer:1,explanation:'In Playwright, specifying a timeout value of `0` disables that specific action or assertion timeout, causing it to wait indefinitely until the condition is satisfied or the overarching test-level timeout expires.'},
{id:4779,topic:'playwright',difficulty:'intermediate',question:'How can you change the global timeout for an entire single test in Playwright?',options:['test.setTimeout(60000) inside the test function','page.setDefaultTimeout(60000)','test.use({ testTimeout: 60000 })','expect.setTimeout(60000)'],answer:0,explanation:'Calling `test.setTimeout(60000)` inside the test callback modifies the maximum allowed execution time for that specific test run, overriding default project timeout settings for slow or extensive end-to-end flows in CI.'},
{id:4780,topic:'playwright',difficulty:'advanced',question:'What is the difference between `page.setDefaultTimeout()` and `page.setDefaultNavigationTimeout()`?',options:['`setDefaultTimeout` applies to all page actions and locators; `setDefaultNavigationTimeout` specifically overrides timeouts for navigation operations (goto, reload, waitForNavigation)','`setDefaultNavigationTimeout` applies only to Firefox','There is no difference; they are aliases','`setDefaultTimeout` only applies to assertions'],answer:0,explanation:'`setDefaultTimeout` changes the default timeout for all locator actions and waits on that page. `setDefaultNavigationTimeout` takes precedence specifically for page navigation commands like `page.goto()`, `page.reload()`, and `page.waitForURL()` operations across your suite.'},
{id:4781,topic:'playwright',difficulty:'beginner',question:'Which Playwright method reloads the current page?',options:['page.refresh()','page.reload()','page.reopen()','page.navigateAgain()'],answer:1,explanation:'`await page.reload()` reloads the current web page, returning the main resource response or null if navigation failed, and auto-waits for the `load` state by default before proceeding to subsequent test statements.'},
{id:4782,topic:'playwright',difficulty:'intermediate',question:'How do you navigate backward and forward in browser history using Playwright?',options:['await page.goBack(); await page.goForward();','await page.history.back(); await page.history.forward();','await page.previous(); await page.next();','await page.navigate(-1); await page.navigate(1);'],answer:0,explanation:'`page.goBack()` and `page.goForward()` navigate one step backward and forward in the browser navigation session history, matching standard browser navigation buttons and resolving when navigation completes successfully without throwing history errors.'},
{id:4783,topic:'playwright',difficulty:'intermediate',question:'What does `page.bringToFront()` do in a multi-tab scenario?',options:['Minimizes all other windows on the operating system','Brings the specified page tab to the foreground and activates it in headed browser mode','Moves the HTML element to the highest CSS z-index','Pushes the page to the top of the test runner queue'],answer:1,explanation:'`await page.bringToFront()` activates the tab, bringing it to the foreground in headed execution environments, ensuring that browser focus events and tab visibility APIs (`document.hidden = false`) trigger as expected across pages.'},
{id:4784,topic:'playwright',difficulty:'advanced',question:'How do you listen for and capture console error messages emitted by the web page in Playwright?',options:['page.on("console", msg => { if (msg.type() === "error") console.log(msg.text()); })','page.onConsoleError(err => console.log(err))','page.catchErrors(err => ... )','page.spy("console.error")'],answer:0,explanation:'`page.on("console", msg => { ... })` captures all console messages produced by the page scripts. You inspect `msg.type()` (`"log"`, `"error"`, `"warn"`, `"info"`) and `msg.text()` to assert on browser logs during test runs.'},
{id:4785,topic:'playwright',difficulty:'advanced',question:'How can you capture unhandled JavaScript exceptions thrown in the page window context in Playwright?',options:['page.on("pageerror", error => { console.error("Unhandled exception:", error); })','page.on("uncaughtException", error => ... )','page.onError(error => ... )','window.addEventListener("error", ... ) via page.evaluate'],answer:0,explanation:'The `"pageerror"` event is emitted on the `Page` object whenever an uncaught exception or unhandled Promise rejection happens inside the page execution context, allowing tests to fail on unexpected runtime client errors.'},
{id:4786,topic:'playwright',difficulty:'intermediate',question:'How can you emulate a specific user agent string in a Playwright test?',options:['test.use({ userAgent: "CustomAgent/1.0" }) or browser.newContext({ userAgent: "..." })','page.setUserAgent("CustomAgent/1.0")','page.headers["User-Agent"] = "CustomAgent/1.0"','playwright.config.ts agent property'],answer:0,explanation:'Configuring `userAgent: "CustomAgent/1.0"` in `test.use()` or passing it to `browser.newContext({ userAgent })` overrides the `navigator.userAgent` property and outgoing HTTP User-Agent request header for that context across all sessions and worker threads seamlessly.'},
{id:4787,topic:'playwright',difficulty:'intermediate',question:'How can you set custom extra HTTP headers (e.g. `X-API-KEY`) for all requests made by a Page or BrowserContext?',options:['await page.setExtraHTTPHeaders({ "X-API-KEY": "secret123" });','page.headers.add("X-API-KEY", "secret123")','context.setHeader("X-API-KEY", "secret123")','page.request.setHeaders({ "X-API-KEY": "secret123" })'],answer:0,explanation:'`page.setExtraHTTPHeaders({ "X-API-KEY": "secret123" })` and `context.setExtraHTTPHeaders(...)` attach the specified HTTP headers to every outgoing network request initiated by the page or any resources it loads dynamically during entire test execution.'},
{id:4788,topic:'playwright',difficulty:'beginner',question:'Which Playwright method unchecks a checkbox or radio button if it is currently checked?',options:['locator.uncheck()','locator.setChecked(false)','Both locator.uncheck() and locator.setChecked(false) are valid','locator.deselect()'],answer:2,explanation:'Both `locator.uncheck()` and `locator.setChecked(false)` are valid Playwright APIs that verify the checkbox is in an unchecked state, automatically clicking it if it was previously checked and doing nothing if already unchecked.'},
{id:4789,topic:'playwright',difficulty:'beginner',question:'How do you select multiple options in a `<select multiple>` HTML dropdown using Playwright?',options:['await locator.selectOption(["value1", "value2"])','await locator.selectMultiple("value1", "value2")','await locator.choose(["value1", "value2"])','await locator.clickOption("value1"); await locator.clickOption("value2");'],answer:0,explanation:'`locator.selectOption(["value1", "value2"])` accepts an array of strings (values, labels, or indices) to select multiple options simultaneously in multi-select dropdown elements, firing input and change events automatically without manual DOM manipulation.'},
{id:4790,topic:'playwright',difficulty:'intermediate',question:'What happens when you call `locator.selectOption({ label: "California" })` on a standard single `<select>` element?',options:['It finds the `<option>` with visible text "California" and selects it, triggering change and input events','It searches for the value attribute "California" only','It creates a new option element labeled "California"','It throws an error if value is not provided'],answer:0,explanation:'Passing `{ label: "California" }` selects the `<option>` matching the user-visible text content and automatically dispatches the necessary `input` and `change` events on the `<select>` DOM element for UI listeners.'},
{id:4791,topic:'playwright',difficulty:'intermediate',question:'How does Playwright handle native JavaScript dialogs (`alert`, `confirm`, `prompt`) if no `page.on("dialog")` handler is registered?',options:['The test runner hangs forever waiting for user input','Playwright automatically dismisses all dialogs so execution is never blocked','Playwright automatically accepts all dialogs with OK','Playwright throws an unhandled DialogException immediately'],answer:1,explanation:'By default, Playwright automatically dismisses (cancels) all dialogs (`dialog.dismiss()`) to prevent the browser from freezing waiting for manual intervention. If you want to accept or input text, register a `page.on("dialog", d => d.accept())` listener.'},
{id:4792,topic:'playwright',difficulty:'intermediate',question:'How do you handle a `prompt()` dialog in Playwright and supply custom input text before accepting it?',options:['page.on("dialog", async dialog => { await dialog.accept("My Input Text"); });','page.promptResponse("My Input Text")','page.dialog.fill("My Input Text")','page.keyboard.type("My Input Text")'],answer:0,explanation:'Registering `page.on("dialog", async dialog => { await dialog.accept("My Input Text"); })` intercepts the dialog when it opens and submits the desired text string into the prompt input before resolving and closing the dialog.'},
{id:4793,topic:'playwright',difficulty:'advanced',question:'What is the purpose of `page.routeFromHAR()` in Playwright?',options:['To export tests into a HAR file format for Postman','To record or replay network requests and responses from an HTTP Archive (HAR) file for deterministic offline testing','To convert HAR files into Selenium test scripts','To measure server-side SQL query performance'],answer:1,explanation:'`page.routeFromHAR("archive.har", { update: false })` serves mocked network responses directly from a recorded HAR archive file. Setting `update: true` records real network traffic into the HAR archive for subsequent offline replay.'},
{id:4794,topic:'playwright',difficulty:'intermediate',question:'What is the difference between `locator.innerText()` and `locator.textContent()` in Playwright?',options:['`innerText` returns only rendered visible text respecting CSS styling; `textContent` returns all text nodes in the element including hidden elements (`display: none`)','`textContent` respects CSS styles; `innerText` does not','`innerText` strips HTML tags; `textContent` preserves them','They are exact aliases with identical performance'],answer:0,explanation:'`locator.innerText()` returns the user-facing visible text, adhering to CSS rules like `display: none` and text transforms. `locator.textContent()` retrieves raw text content from the DOM node directly, including hidden element text.'},
{id:4795,topic:'playwright',difficulty:'intermediate',question:'Which Playwright assertion checks that an element contains a specific class attribute value?',options:['await expect(locator).toHaveClass(/active/)','await expect(locator).toContainClassName("active")','await expect(locator).toBeClass("active")','expect(locator.className).toBe("active")'],answer:0,explanation:'`await expect(locator).toHaveClass("active")` or `toHaveClass(/active/)` asserts that the element\'s class attribute contains or matches the specified string or RegExp, with built-in auto-waiting retry support throughout asynchronous CSS styling and layout state transitions.'},
{id:4796,topic:'playwright',difficulty:'intermediate',question:'Which assertion verifies that an `<input>` element has a specific value entered?',options:['await expect(locator).toHaveValue("john_doe")','await expect(locator).toHaveText("john_doe")','await expect(locator).toBeValue("john_doe")','expect(locator.value()).toBe("john_doe")'],answer:0,explanation:'`await expect(locator).toHaveValue("john_doe")` asserts the value property of an input, textarea, or select element. `toHaveText()` checks the inner text of an element, which does not apply to input values in form controls.'},
{id:4797,topic:'playwright',difficulty:'beginner',question:'Which Playwright assertion checks that a list of items has a specific count?',options:['await expect(locator).toHaveCount(5)','await expect(locator.count()).toBe(5)','expect(locator).toHaveLength(5)','await expect(locator).toBeCount(5)'],answer:0,explanation:'`await expect(locator).toHaveCount(5)` is the web-first assertion that retries until the number of DOM nodes matched by the locator equals 5. Calling `locator.count()` is an instantaneous query without auto-waiting and can cause flakiness.'},
{id:4798,topic:'playwright',difficulty:'intermediate',question:'What does `locator.filter({ hasText: "Active" })` do in Playwright?',options:['Filters an existing locator to only include elements that contain the specified text anywhere inside their subtree','Clicks on elements that have text "Active"','Deletes elements without text "Active" from DOM','Replaces the locator with a new global search for "Active"'],answer:0,explanation:'`locator.filter({ hasText: "Active" })` narrows down a multi-match locator list to only those elements whose subtree contains the matching text or regular expression, without losing the original locator\'s structural context.'},
{id:4799,topic:'playwright',difficulty:'advanced',question:'How can you filter a list of table rows `page.getByRole("row")` to find the row containing a button named "Delete"?',options:['page.getByRole("row").filter({ has: page.getByRole("button", { name: "Delete" }) })','page.getByRole("row").withChild("button:Delete")','page.getByRole("row").find("button", { name: "Delete" })','page.getByRole("row").hasElement(page.locator("button"))'],answer:0,explanation:'The `filter({ has: locator })` option allows filtering parent locators by requiring them to contain an element matching the child locator. This isolates the exact table row containing the "Delete" button.'},
{id:4800,topic:'playwright',difficulty:'intermediate',question:'What is the purpose of `locator.or(otherLocator)` introduced in Playwright?',options:['Matches elements that satisfy either the first locator OR the second locator','Executes two clicks in parallel','Runs a conditional branch test based on locator existence','Combines XPath and CSS into one query'],answer:0,explanation:'`locator.or(otherLocator)` creates a composite locator that matches elements satisfying either locator. This is useful when an element can appear in one of two states (e.g. "Submit" button or "Proceed" button).'},
{id:4801,topic:'playwright',difficulty:'intermediate',question:'What does `locator.and(otherLocator)` do in Playwright?',options:['Matches elements that simultaneously satisfy both locator conditions','Clicks both locators sequentially','Creates a parent-child relationship between locators','Merges text from two elements'],answer:0,explanation:'`locator.and(otherLocator)` narrows matches to elements that satisfy both locator conditions simultaneously, such as `page.getByRole("button").and(page.getByTitle("Save Changes"))`, combining multiple query criteria into a single resilient, unambiguous locator target for robust automation scripts.'},
{id:4802,topic:'playwright',difficulty:'beginner',question:'How do you double-click on an element in Playwright?',options:['await locator.dblclick()','await locator.click({ count: 2 })','Both locator.dblclick() and locator.click({ clickCount: 2 }) are valid','await locator.doubleClick()'],answer:2,explanation:'Both `await locator.dblclick()` and `await locator.click({ clickCount: 2 })` dispatch a standard double-click event sequence (pointerdown, pointerup, click, pointerdown, pointerup, click, dblclick) to the element with full auto-waiting and actionability verification.'},
{id:4803,topic:'playwright',difficulty:'beginner',question:'How do you right-click on an element using Playwright?',options:['await locator.click({ button: "right" })','await locator.rightClick()','await locator.contextMenu()','await page.mouse.rightClick(locator)'],answer:0,explanation:'Passing `{ button: "right" }` to `locator.click()` simulates a right mouse button click, triggering the `contextmenu` event and opening custom context menus in web applications reliably without requiring low-level mouse coordinates.'},
{id:4804,topic:'playwright',difficulty:'intermediate',question:'How can you hover over an element and then press a keyboard shortcut in Playwright?',options:['await locator.hover(); await page.keyboard.press("Control+S");','await locator.mouseOver(); await page.sendKey("Ctrl+S");','await locator.focus(); await locator.pressKey("Control+S");','await page.hoverAndType(locator, "Control+S");'],answer:0,explanation:'`await locator.hover()` scrolls the element into view and positions the mouse over its bounding box, followed by `await page.keyboard.press("Control+S")` to dispatch the keyboard shortcut directly to the focused target in the DOM.'},
{id:4805,topic:'playwright',difficulty:'advanced',question:'How can you mock system time or clock in Playwright for testing time-dependent features?',options:['await page.clock.setFixedTime(new Date("2025-01-01T00:00:00Z"));','await page.evaluate(() => Date.now = () => 1234567890);','test.use({ fakeTimers: true });','page.setSystemDate("2025-01-01")'],answer:0,explanation:'Playwright provides the dedicated `page.clock` API (e.g. `page.clock.setFixedTime()`, `page.clock.fastForward()`, `page.clock.install()`) to deterministically control and simulate browser timers, `Date.now()`, `setTimeout`, and `setInterval` without introducing physical delays into your automated test runs.'},
{id:4806,topic:'playwright',difficulty:'advanced',question:'How does `page.clock.fastForward("01:00")` or `page.clock.runFor(5000)` work in Playwright?',options:['It advances virtual time by the specified duration, immediately triggering all scheduled setTimeout/setInterval callbacks without real-world delay','It sleeps the Node.js process for 5000 milliseconds','It accelerates CSS animation speeds','It speeds up video playback in the page'],answer:0,explanation:'`page.clock.fastForward()` or `runFor()` advances virtual clock time instantly in the browser environment, triggering any pending timer callbacks (such as countdowns or session timeouts) without waiting in real time during test execution.'},
{id:4807,topic:'playwright',difficulty:'intermediate',question:'What is the function of `page.evaluateHandle()` compared to `page.evaluate()`?',options:['`evaluateHandle` returns an in-page object reference (JSHandle or ElementHandle) within the browser memory, whereas `evaluate` serializes the return value into JSON to pass to Node.js','`evaluateHandle` only executes in WebKit','`evaluate` cannot take arguments; `evaluateHandle` can','`evaluateHandle` is deprecated'],answer:0,explanation:'`page.evaluate()` serializes the result back to Node.js as JSON primitives. `page.evaluateHandle()` preserves a handle to the actual in-memory JavaScript/DOM object in the browser, allowing subsequent operations on that handle across test steps.'},
{id:4808,topic:'playwright',difficulty:'intermediate',question:'What does `test.slow()` do when placed inside a Playwright test file or test block?',options:['It slows down browser action execution for visual debugging','It triples the default timeout for the test to accommodate known slow operations','It flags the test as deprecated','It limits worker CPU usage'],answer:1,explanation:'Calling `test.slow()` marks the test as slow and automatically triples the configured test timeout (e.g. increasing a 30s timeout to 90s), preventing premature timeout failures on heavy end-to-end scenarios during CI runs.'},
{id:4809,topic:'playwright',difficulty:'beginner',question:'What does `test.fail()` do when declared inside a Playwright test?',options:['It fails the entire test suite immediately','It marks the test as expected to fail; if the test fails it passes, and if it unexpectedly passes, Playwright reports an error','It skips the test completely','It retries the test 10 times'],answer:1,explanation:'`test.fail()` documents a known defect. Playwright expects the test to fail: if it fails, the test run is marked green. If the test unexpectedly passes (e.g., bug was resolved), Playwright flags it as a failure.'},
{id:4810,topic:'playwright',difficulty:'intermediate',question:'How can you organize test suites hierarchically with shared setup and teardown in Playwright?',options:['Using `test.describe("Suite Name", () => { ... })` blocks with nested `test.beforeEach()` and `test.afterEach()` hooks','Using plain JavaScript switch statements','By naming test files with numerical prefixes','By creating separate npm scripts per test group'],answer:0,explanation:'`test.describe("Group", () => { ... })` blocks group related tests logically. Nested hooks (`beforeAll`, `beforeEach`, `afterEach`, `afterAll`) execute in hierarchical order within the block, enabling clean scoped test organization across suites.'}
]);
